import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as l,c as i,o as a,af as e,b as o,w as r,a as h,G as s,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"数据、预训练与 Scaling（桥接）","description":"Data → Pretraining → Base model 链条的工程含义——能力上限冻结于预训练，由此解释 knowledge cutoff 的根源、厂商定价档位的结构与「为什么某模型在你的任务上不可靠」；训练细节归 Learn LLM。","frontmatter":{"title":"数据、预训练与 Scaling（桥接）","description":"Data → Pretraining → Base model 链条的工程含义——能力上限冻结于预训练，由此解释 knowledge cutoff 的根源、厂商定价档位的结构与「为什么某模型在你的任务上不可靠」；训练细节归 Learn LLM。","domain":"tech","tags":["tech","model-lifecycle","bridge","pretraining","scaling"],"navOrder":13,"topicId":"data-pretraining-scaling","layer":"1","status":"bridge","nodeType":"concept","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/08-tinygpt"}],"prerequisites":["architecture"],"next":["appendices-model-lifecycle"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/data-pretraining-scaling.md","filePath":"zh/tech/01-model-lifecycle/data-pretraining-scaling.md","lastUpdated":1791115887000}'),g={name:"zh/tech/01-model-lifecycle/data-pretraining-scaling.md"};function p(f,t,E,b,u,m){const d=l("Mermaid");return a(),i("div",null,[t[1]||(t[1]=e('<blockquote><p><strong>在哪一组</strong>：组 01 · 模型生命周期（桥接组）｜ <strong>上一组出口</strong>：能判断知识归属、并为需求选出最低复杂度方案（00-map 组） ｜ <strong>本页出口</strong>：能解释 knowledge cutoff 的根源，并用「能力上限冻结于预训练」约束模型选型、时效知识方案与版本升级回归 <strong>前置</strong>：<a href="./architecture.html">模型架构（桥接）</a> ｜ <strong>下一步</strong>：<a href="./post-training/">后训练</a>（组内子组）；深层原理去 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：base model 的能力上限在预训练结束那一刻冻结。数据配比、规模与算力的权衡（scaling law）决定「这个模型会什么、不会什么」。这条链解释三件应用层的事：knowledge cutoff 的根源、厂商模型档位与定价的结构、以及为什么某个模型在你的任务上不可靠。本页只讲这条链的工程含义；预训练全流程的从零实现归 <a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">Learn LLM 第 8 章</a>。</p><h3 id="链条" tabindex="-1">链条 <a class="header-anchor" href="#链条" aria-label="Permalink to &quot;链条&quot;">​</a></h3>',4)),(a(),o(c,null,{default:r(()=>[s(d,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20D%5B%22%E6%95%B0%E6%8D%AE%E5%B7%A5%E7%A8%8B%3Cbr%2F%3E%E9%87%87%E9%9B%86%20%C2%B7%20%E6%B8%85%E6%B4%97%20%C2%B7%20%E5%8E%BB%E9%87%8D%20%C2%B7%20%E9%85%8D%E6%AF%94%22%5D%20--%3E%20P%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%3Cbr%2F%3E%E4%B8%8B%E4%B8%80%20token%20%E7%9B%AE%E6%A0%87%20%C2%B7%20%E5%A4%A7%E8%A7%84%E6%A8%A1%E7%AE%97%E5%8A%9B%22%5D%0A%20%20%20%20P%20--%3E%20B%5B%22Base%20model%3Cbr%2F%3E%E8%83%BD%E5%8A%9B%E4%B8%8A%E9%99%90%E5%9C%A8%E6%AD%A4%E5%86%BB%E7%BB%93%22%5D%0A%20%20%20%20B%20--%3E%20PT%5B%22%E5%90%8E%E8%AE%AD%E7%BB%83%EF%BC%88%E7%BB%84%E5%86%85%E4%B8%8B%E4%B8%80%E7%AB%99%EF%BC%89%3Cbr%2F%3ESFT%20%C2%B7%20RLHF%20%C2%B7%20PEFT%22%5D%0A%20%20%20%20B%20-.-%3E%7C%E8%AE%AD%E7%BB%83%E6%95%B0%E6%8D%AE%E6%88%AA%E6%AD%A2%20%3D%20%E7%9F%A5%E8%AF%86%E6%88%AA%E6%AD%A2%7C%20K%5B%22knowledge%20cutoff%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[h(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h3 id="三个工程后果" tabindex="-1">三个工程后果 <a class="header-anchor" href="#三个工程后果" aria-label="Permalink to &quot;三个工程后果&quot;">​</a></h3><ol><li><strong>Knowledge cutoff 的根源在这条链</strong>。模型的事实知识来自预训练语料的收集截止点；后训练与产品包装改变行为，不更新权重里的世界知识。时间敏感的事实必须走检索（<a href="./../04-grounding/rag.html">RAG</a>）；cutoff 是要核对的接口属性，不是缺陷。</li><li><strong>Scaling law 是厂商档位的结构</strong>。Kaplan 与 Chinchilla 两篇工作确立了「损失随参数、数据、算力按可预测规律下降，且参数与数据存在算力最优配比」（本页不复述具体指数）。工程翻译：能力档位是可购买的算力决策，厂商把这条曲线切成分层定价——你的选型就是在这条曲线上选点。</li><li><strong>数据质量决定任务可靠性</strong>。你的领域在预训练语料中的占比与清洗质量决定模型「开箱」的表现；评测集数据若混入预训练语料（contamination），榜单分数会被抬高。单一排行榜不可作为选型依据——用你自己的评估集（<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>、<a href="./../08-production/evaluation.html">评估</a>）。</li></ol><h2 id="_2-何时跳转" tabindex="-1">2. 何时跳转 <a class="header-anchor" href="#_2-何时跳转" aria-label="Permalink to &quot;2. 何时跳转&quot;">​</a></h2><p>本页无可运行产物；按下表路由：</p><table tabindex="0"><thead><tr><th>症状 / 问题</th><th>该读哪</th><th>为什么</th></tr></thead><tbody><tr><td>想看预训练从零跑通（TinyGPT、checkpoint、loss 曲线）</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">第 8 章</a></td><td>预训练全流程的 canonical</td></tr><tr><td>训练为什么 / 何时会不稳定</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/06-training-stability" target="_blank" rel="noreferrer">第 6 章</a></td><td>训练稳定性工程</td></tr><tr><td>scaling law 的原始论述</td><td>Kaplan / Chinchilla 论文（见资料表）</td><td>一手来源，本页只留结论</td></tr><tr><td>时间敏感的知识怎么办</td><td>本仓 <a href="./../04-grounding/rag.html">RAG</a></td><td>时效知识走检索不走权重</td></tr><tr><td>怎么可靠地选模型</td><td>本仓 <a href="./../08-production/evaluation.html">评估</a> + evals 站</td><td>榜单可能被污染，自建评估集</td></tr><tr><td>新知识要不要微调进权重</td><td>组内 <a href="./post-training/sft.html">SFT（桥接）</a></td><td>动权重的决策门</td></tr></tbody></table><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>一段定位：预训练是把「下一 token 预测」目标在海量语料上跑足够多步；scaling law 是这条流水线的经验规律而非物理定律——它指导厂商的训练预算分配，并以模型档位与定价的形式被你消费。数据工程的细节（去重、配比、过滤）与训练稳定性归 Learn LLM 第 6、8 章（retrievedAt 2026-09-01）。本仓的停止点在「能力上限冻结于预训练」：这不是价值判断，而是改不动已发布权重的工程事实。</p><h2 id="_4-工程决策影响" tabindex="-1">4. 工程决策影响 <a class="header-anchor" href="#_4-工程决策影响" aria-label="Permalink to &quot;4. 工程决策影响&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工程决策</th><th>由这条链推出的判断</th><th>错误预期会付出的代价</th></tr></thead><tbody><tr><td>模型选型</td><td>上限冻结于预训练；榜单分数可能被 contamination 抬高</td><td>按 leaderboard 选型，上线后任务表现不符</td></tr><tr><td>知识时效方案</td><td>cutoff 是硬属性，不会因为提示而消失</td><td>指望新模型「应该知道」最近发生的事</td></tr><tr><td>版本升级</td><td>新版本 = 新数据 + 新预训练，工程假设可能全部变化</td><td>直接切 latest 版本，未跑回归评估</td></tr><tr><td>成本结构理解</td><td>档位定价是 scaling 曲线的切片</td><td>混淆「更贵」与「更适合我的任务」</td></tr><tr><td>领域可靠性验证</td><td>语料占比决定开箱表现</td><td>假设专业领域零样本可靠，不做样本测试</td></tr></tbody></table><p>维护规则（替代 runbook）：Learn LLM 第 6/8 章结构调整时重验本页 deep-link 并更新 <code>lastVerified</code>；主流模型的具体 cutoff 日期与语料构成是厂商披露信息，本页不维护清单——使用时以各厂商模型卡为准。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><table tabindex="0"><thead><tr><th>级</th><th>读什么</th><th>为什么是这个顺序</th></tr></thead><tbody><tr><td>Beginner</td><td>本页 + <a href="./index.html">组导览</a></td><td>建立「链条 → 三个工程后果」的映射</td></tr><tr><td>Builder</td><td><a href="./../04-grounding/rag.html">RAG</a> + <a href="./../08-production/evaluation.html">评估</a></td><td>把 cutoff 与可靠性问题接到主线方案</td></tr><tr><td>Operator</td><td><a href="./../08-production/evaluation.html">评估</a> 的版本回归视角</td><td>每次模型升级先跑回归</td></tr><tr><td>Researcher</td><td>Learn LLM 第 6、8 章 + 两篇 scaling 论文</td><td>下沉到预训练与规模规律的一手论述</td></tr></tbody></table><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>层级</th><th>canonical URL</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>Learn LLM 第 8 章 · TinyGPT</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/08-tinygpt</a></td><td>预训练、过拟合、checkpoint 与恢复的从零实现</td><td>跑通一次预训练</td></tr><tr><td>Learn LLM 第 6 章 · 训练稳定性</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/06-training-stability" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/06-training-stability</a></td><td>训练稳定性是工程问题</td><td>理解训练诊断</td></tr><tr><td>Scaling Laws for Neural Language Models（Kaplan et al., 2020）</td><td>L4</td><td><a href="https://arxiv.org/abs/2001.08361" target="_blank" rel="noreferrer">https://arxiv.org/abs/2001.08361</a></td><td>损失随参数/数据/算力的幂律关系的系统量化</td><td>读 loss-vs-scale 图</td></tr><tr><td>Training Compute-Optimal LLMs（Chinchilla，Hoffmann et al., 2022）</td><td>L4</td><td><a href="https://arxiv.org/abs/2203.15556" target="_blank" rel="noreferrer">https://arxiv.org/abs/2203.15556</a></td><td>参数与数据存在算力最优配比</td><td>对照 Kaplan 结论</td></tr><tr><td>evals 站</td><td>E</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>评估方法与发布证据的 canonical sibling</td><td>建自己的评估集</td></tr></tbody></table><p>（Learn LLM 章节经其章节目录核验、arXiv 链接为稳定 abs 地址，retrievedAt 均为 2026-09-01。）</p><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：需要具体训练预算、数据量或语料配比估算的决策（如自训模型的算力规划）属于 Learn LLM 或 ML 团队，不是本页——请下沉断言，不要在此扩写。</li><li>未决：contamination 的公开检测方法与各模型卡披露口径不统一，本页未逐模型核验；选型时以自建评估集结果为准。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>训练数据工程与实验方法：Learn LLM 第 6、8 章——本仓到此为止。</li><li>给模型补充时效知识：本仓 <a href="./../04-grounding/">04-grounding 组</a>。</li><li>组内下一站：<a href="./post-training/">后训练</a>（SFT / RLHF / PEFT 的工程决策桥）。</li></ul>',20))])}const x=n(g,[["render",p]]);export{k as __pageData,x as default};
